unit["purpose"]="Integrar la cadena biomédica completa en un expediente auditable y reproducible que conecte arquitectura, presupuestos, configuración, procedencia, trazabilidad, cambios, discrepancias y límites, de modo que otra persona pueda reconstruir qué se evaluó y qué afirmaciones siguen fuera del alcance."
unit["topics"]=[
 topic("01","1. Arquitectura e interfaces como contratos verificables",[
  sub("01",1,"El sistema empieza antes del primer componente",claim_specs[0][0]+" La arquitectura representa además operador, entorno, procedimiento, mantenimiento y exclusiones cuando influyen en el resultado."),
  sub("01",2,"Una interfaz no es solo un cable",claim_specs[1][0]+" También puede existir una interfaz de datos, reloj, procedimiento o usuario; cada una necesita una pregunta de verificación propia."),
  sub("01",3,"El caso límite pertenece a la arquitectura","La integración debe comprobar valores nominales y bordes del dominio: máximos, mínimos, arranque, saturación, pérdida de reloj, datos ausentes, cambios de configuración y recuperación. Un diagrama nominal sin casos límite no caracteriza la arquitectura operativa."),
 ],[claim_specs[0][0],claim_specs[1][0],"Los casos límite forman parte de la arquitectura que debe verificarse."]),
 topic("02","2. Presupuestos integrados y compensaciones",[
  sub("02",1,"Los presupuestos compiten por margen",claim_specs[2][0]+" Aumentar ganancia puede mejorar utilización del ADC y simultáneamente reducir margen ante artefactos; reducir banda puede bajar ruido y aumentar distorsión temporal."),
  sub("02",2,"Nominal no equivale a peor caso",claim_specs[3][0]+" Deben marcarse qué contribuciones se combinan estadísticamente, cuáles se suman conservadoramente y cuáles comparten causas comunes."),
  sub("02",3,"Cada presupuesto termina en un requisito","Un presupuesto es útil cuando cada margen se puede rastrear a un requisito o riesgo y a una prueba. Si un margen de 10 % no tiene razón documentada, es una convención, no evidencia de suficiencia."),
 ],[claim_specs[2][0],claim_specs[3][0],"Cada margen del presupuesto debe tener una justificación trazable."]),
 topic("03","3. Configuración, baseline y control de cambios",[
  sub("03",1,"La configuración debe poder nombrarse",claim_specs[4][0]+" Para un sistema computacional o mixto incluye al menos versiones de datos, código, dependencias, parámetros, firmware y artefactos de referencia pertinentes."),
  sub("03",2,"Una baseline es recuperable, no decorativa",claim_specs[5][0]+" Una etiqueta sin contenido identificado no permite reproducir ni auditar la condición evaluada."),
  sub("03",3,"Versionar código no captura todo el sistema",claim_specs[6][0]+" El expediente debe decidir qué elementos son configuration items y cuáles son datos técnicos gestionados, manteniendo vínculos entre ambos."),
 ],[claim_specs[4][0],claim_specs[5][0],claim_specs[6][0]]),
 topic("04","4. Procedencia y reproducibilidad computacional",[
  sub("04",1,"Procedencia explica cómo se produjo el artefacto",claim_specs[7][0]+" Para un resultado sintético, el expediente puede representar dataset como entidad, ejecución como actividad y script/operador como agente o asociación relevante."),
  sub("04",2,"Los datos técnicos necesitan metadatos",claim_specs[8][0]+" Un CSV sin unidades, esquema, versión y origen puede ser legible y aun así no ser interpretable o reutilizable de forma segura."),
  sub("04",3,"Reproducir exige más que abrir el repositorio",claim_specs[9][0]+" "+claim_specs[10][0]+" Por eso una reproducción se registra como un nuevo evento con sus propias salidas y comparación contra resultados esperados."),
 ],[claim_specs[7][0],claim_specs[8][0],claim_specs[9][0]]),
 topic("05","5. Manifiestos, identidad y trazabilidad de evidencia",[
  sub("05",1,"El manifiesto fija los ingredientes de una ejecución",claim_specs[11][0]+" Debe permitir diferenciar dos ejecuciones que usaron el mismo script pero distinta entrada, parámetro o dependencia."),
  sub("05",2,"Identidad no es validez",claim_specs[12][0]+" Un hash es útil como control de integridad, mientras la validez requiere fuentes, modelos, criterios y revisión del significado."),
  sub("05",3,"La matriz preserva razones e historia",claim_specs[13][0]+" Los identificadores persistentes deben mantenerse separados de la posición curricular o del nombre visible para que una reorganización no falsifique procedencia."),
 ],[claim_specs[11][0],claim_specs[12][0],claim_specs[13][0]]),
 topic("06","6. Cambio, auditoría y cierre limitado",[
  sub("06",1,"Cambiar una pieza puede invalidar evidencia distante",claim_specs[14][0]+" El análisis de impacto recorre dependencias hacia requisitos, riesgos y resultados antes de decidir qué evidencia puede conservarse y qué debe repetirse."),
  sub("06",2,"Las discrepancias conservan memoria técnica",claim_specs[15][0]+" La auditoría debe poder reconstruir qué ocurrió incluso cuando el problema ya fue corregido."),
  sub("06",3,"El cierre se prueba y conserva límites",claim_specs[16][0]+" "+claim_specs[17][0]),
 ],[claim_specs[14][0],claim_specs[15][0],claim_specs[17][0]]),
]

unit["examples"]=[
{"id":"BIOINST-U10-EJ01","title":"Interfaz correcta por separado, incompatible al integrar","scenario":"Un acondicionador entrega ±2.5 V y el ADC posterior acepta 0–3.3 V; ambos cumplen sus fichas individuales.","reasoning_steps":["Escribir contrato de interfaz con rango y referencia.","Detectar que tensiones negativas quedan fuera del ADC.","Relacionar la incompatibilidad con saturación/recorte y requisito de rango.","Corregir arquitectura o nivel/referencia y repetir verificación."],"interpretation":"Cumplir especificaciones de componente no basta si los contratos entre bloques son incompatibles.","limitations":["Caso sintético; no selecciona un componente real."]},
{"id":"BIOINST-U10-EJ02","title":"Trade-off entre banda, ruido y latencia","scenario":"Un filtro reduce ruido RMS de 12 a 7 µV, pero aumenta el tiempo de establecimiento de 0.4 a 1.8 s mientras el requisito temporal es ≤1.0 s.","reasoning_steps":["Registrar mejora de ruido.","Comparar tiempo con requisito temporal.","No compensar un fallo temporal con una métrica de ruido mejor.","Buscar diseño alternativo o revisar requisito solo mediante cambio controlado."],"interpretation":"Los presupuestos deben decidirse conjuntamente; una mejora local puede violar otro requisito.","limitations":["Números educativos sin interpretación clínica."]},
{"id":"BIOINST-U10-EJ03","title":"Baseline incompleta","scenario":"El repositorio tiene tag v1.0, pero el dataset fue sobrescrito y no se guardó la versión de una dependencia.","reasoning_steps":["Listar configuration items esperados.","Detectar que el tag identifica código pero no todo el estado.","Marcar datos/dependencia como brechas de configuración.","No afirmar que v1.0 es reproducible hasta recuperar o declarar la pérdida."],"interpretation":"Una etiqueta de versión no es una baseline recuperable si faltan artefactos que afectaron el resultado.","limitations":["No prescribe una plataforma concreta de control de versiones."]},
{"id":"BIOINST-U10-EJ04","title":"Cadena de procedencia de un resultado","scenario":"raw.csv se filtra con preprocess.py y genera clean.csv; analyze.py produce metrics.json.","reasoning_steps":["Identificar raw/clean/metrics como entidades versionadas.","Registrar preprocesado y análisis como actividades con parámetros.","Vincular scripts/configuración a cada actividad.","Guardar hashes/IDs y tiempos como ayudas de integridad/procedencia."],"interpretation":"La cadena permite reconstruir qué transformaciones produjeron metrics.json; no demuestra que el análisis sea científicamente correcto.","limitations":["Modelo PROV simplificado."]},
{"id":"BIOINST-U10-EJ05","title":"Reproducción falla por el entorno","scenario":"Mismos datos y código producen un resultado diferente tras actualizar una librería no fijada.","reasoning_steps":["Comparar manifiestos de ambas ejecuciones.","Identificar versión de dependencia como cambio de configuración.","Restaurar el entorno anterior o evaluar el impacto de la nueva versión.","Registrar ambas salidas sin sobrescribir el historial."],"interpretation":"Código y datos iguales no garantizan reproducibilidad si las condiciones computacionales relevantes cambiaron.","limitations":["La diferencia no prueba por sí sola qué versión es correcta."]},
{"id":"BIOINST-U10-EJ06","title":"Cambio de sensor y análisis de impacto","scenario":"Se sustituye un sensor por otro con rango y sensibilidad distintos después de cerrar pruebas de U8/U9.","reasoning_steps":["Registrar solicitud y nueva configuración.","Recorrer interfaces/presupuestos afectados: carga, ganancia, ADC, calibración e incertidumbre.","Recorrer requisitos/riesgos/pruebas dependientes.","Definir qué evidencia se conserva y cuál debe repetirse antes de una nueva baseline."],"interpretation":"El cambio no invalida automáticamente todo, pero tampoco permite reutilizar evidencia sin análisis de dependencia.","limitations":["Decisión educativa; un sistema real necesita su proceso aplicable."]},
]

unit["activities"]=[{"id":"BIOINST-U10-ACT01","title":"Proyecto integrador: expediente reproducible de una cadena biomédica sintética","purpose":"Construir un paquete técnico que permita a otra persona reconstruir arquitectura, configuración, datos, análisis, evidencia, cambios y límites de un sistema sintético sin depender de explicaciones orales del autor.","prerequisite_unit_ids":["BIOINST-U09"],"estimated_duration_minutes":300,"instructions":["Elegir un uso previsto educativo y congelar una baseline inicial con identificadores para arquitectura, requisitos, riesgos, datos, código, parámetros y fuentes; no usar personas ni hardware médico energizado.","Integrar resultados de U1–U9 en una arquitectura con contratos de interfaz y presupuestos de rango, ganancia, banda, ruido, tiempo e incertidumbre, indicando margen y peor caso.","Crear un manifiesto por ejecución que identifique entradas, hashes/IDs, código, dependencias, configuración, semillas, comandos, entorno y salidas; registrar procedencia de al menos dos transformaciones.","Introducir un cambio controlado —por ejemplo sensor, filtro, tasa de muestreo o algoritmo— y realizar un análisis de impacto que decida qué requisitos, riesgos, pruebas y resultados siguen vigentes y cuáles deben repetirse.","Entregar el paquete a una segunda ejecución limpia —automatizada o manual documentada—, comparar resultados y cerrar únicamente las afirmaciones respaldadas por evidencia; dejar brechas y revisión humana como estados explícitos."],"tasks":["Dibujar una arquitectura extremo a extremo y completar una tabla de al menos diez interfaces con cantidad, unidad, rango, referencia, formato, temporización y prueba asociada.","Construir cinco presupuestos integrados (rango/ganancia, banda, ruido, tiempo e incertidumbre) con requisitos, margen, dependencias y al menos un escenario de peor caso.","Crear la matriz bidireccional `necesidad → requisito → riesgo/control → diseño → prueba → resultado/discrepancia` y ejecutar una consulta inversa desde tres resultados hasta su razón de origen.","Definir la baseline B0 con inventario de configuration items y datos técnicos; registrar versiones/IDs de dataset, código, configuración, dependencias, fuentes y documentación.","Generar un manifiesto de ejecución R1 y un grafo/tablas de procedencia que permitan reconstruir al menos dos transformaciones desde entrada hasta resultado.","Intentar reproducir R1 desde un entorno limpio usando únicamente el expediente; registrar coincidencias, diferencias, dependencias implícitas y pasos manuales descubiertos.","Aplicar un cambio C1, crear baseline B1 y ejecutar análisis de impacto sobre interfaces, presupuestos, requisitos, riesgos, calibración/incertidumbre y pruebas; repetir solo la evidencia justificadamente afectada.","Realizar una auditoría final buscando evidencia huérfana, artefactos sin versión, hashes sin procedencia, discrepancias borradas, relaciones rotas y afirmaciones que exceden el alcance; convertir cada hallazgo en brecha/acción trazable."],"deliverables":["Arquitectura y tabla de interfaces con presupuestos integrados y escenarios límite.","Matriz bidireccional de trazabilidad con necesidades, requisitos, riesgos, controles, pruebas, resultados y discrepancias.","Inventario B0/B1 de configuración y datos técnicos con versiones, IDs, fuentes y estado.","Manifiestos de ejecución y registro de procedencia para R1 y su reproducción, con comandos/entorno suficientes.","Registro C1 de cambio e impacto con evidencia conservada, invalidada o repetida y justificación de cada decisión.","Expediente final comprimible/publicable con README de reconstrucción, resultados, brechas, límites, preguntas de revisión humana y síntesis de cierre de 2–3 páginas."],"checking_criteria":["La arquitectura parte del uso/mensurando y cada interfaz declara cantidad, unidad, rango, referencia, formato y temporización.","Los cinco presupuestos enlazan requisitos, márgenes, dependencias y peor caso; ninguna mejora local oculta una violación de otro presupuesto.","La trazabilidad funciona hacia adelante y hacia atrás y conserva identificadores persistentes.","B0/B1 permiten identificar el estado de datos, código, configuración, dependencias y documentación en cada punto.","La procedencia distingue origen, transformaciones y participantes/artefactos sin tratar hashes como prueba de validez.","El manifiesto incluye entradas, parámetros, entorno y salidas suficientes para comparar ejecuciones.","La reproducción desde entorno limpio registra diferencias en lugar de ajustarlas o borrarlas hasta coincidir.","El análisis C1 identifica selectivamente evidencia afectada y conserva la historia de la configuración anterior.","Las discrepancias originales y sus disposiciones permanecen auditables; no se sobrescriben con el resultado corregido.","El cierre declara configuración, alcance, brechas y revisión humana pendiente y niega que el expediente demuestre conformidad, seguridad o validez clínica."],"status":"curated_pending_expert_review"}]

assessment["purpose"]="Evaluar integración de arquitectura, presupuestos, configuración, procedencia, reproducibilidad, trazabilidad y cambio mediante casos de auditoría de un expediente técnico."
