def norm(s): return re.sub(r"\s+"," ",s.strip().casefold())
def next_gid():
    nums=[int(m.group(1)) for e in glossary["entries"] if (m:=re.fullmatch(r"BIOINST-GLO-(\d+)",e.get("id","")))]
    return f"BIOINST-GLO-{max(nums)+1:03d}"
def ensure(term,definition,sids,locators,status="verified_contextually"):
    e=next((x for x in glossary["entries"] if norm(x.get("term",""))==norm(term)),None)
    if e is None:
        e={"id":next_gid(),"term":term,"definition":definition,"unit_ids":[],"source_ids":[],"verification_status":status};glossary["entries"].append(e)
    e["definition"]=definition;e["unit_ids"]=sorted(set(e.get("unit_ids",[]))|{"BIOINST-U10"});e["source_ids"]=sids;e["verification_status"]=status;e["source_locators"]=[{"source_id":s,"locator":l} for s,l in locators]
    return e["id"]

